// Generates the site's brand assets from the design source docs/design/brand.html
// ("Góc Bộ Tộc" v2). Re-run after the designer updates brand.html:
//   npm run brand
// Outputs (all generated, do not edit by hand):
//   public/brand/**.svg                 logos, mascot, illustrations (static files: zero JS cost)
//   src/app/icon.svg                    favicon (Next metadata file convention)
//   src/shared/design/themes.generated.css   seasonal skins as token overrides
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const root = new URL("..", import.meta.url).pathname;
const html = readFileSync(join(root, "docs/design/brand.html"), "utf8");

const write = (rel, content) => {
  const path = join(root, rel);
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
  console.log(`  ${rel}`);
};

/** HTML split into { title, body } by <h2>. */
const sections = [];
{
  const parts = html.split(/(<h2[^>]*>[\s\S]*?<\/h2>)/);
  let title = "(top)";
  for (const p of parts) {
    const m = p.match(/^<h2[^>]*>([\s\S]*?)<\/h2>$/);
    if (m) title = m[1].replace(/<[^>]+>/g, "").replace(/&amp;/g, "&").trim();
    else sections.push({ title, body: p });
  }
}
const section = (prefix) => {
  const s = sections.find((x) => x.title.startsWith(prefix));
  if (!s) throw new Error(`brand.html: section "${prefix}" not found`);
  return s.body;
};
/** Each <svg>…</svg> with the plain text that follows it (the caption). */
function svgsWithCaptions(body) {
  return [...body.matchAll(/<svg[\s\S]*?<\/svg>/g)].map((m) => {
    const after = body.slice(m.index + m[0].length, m.index + m[0].length + 300);
    const caption = after.replace(/<svg[\s\S]*$/, "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
    return { svg: m[0], caption };
  });
}
const fileName = (caption) => caption.match(/([a-z0-9-]+)\.svg/)?.[1];
const withXmlHeader = (svg) => `<?xml version="1.0" encoding="UTF-8"?>\n${svg.trim()}\n`;

console.log("Logos");
for (const { svg, caption } of svgsWithCaptions(section("Logo"))) {
  const name = fileName(caption);
  // The full wordmark is drawn as text in <Logo> (site renamed “Góc Bộ Tộc”, ADR-011).
  if (name && !name.startsWith("logo-full")) write(`public/brand/${name}.svg`, withXmlHeader(svg));
}
const mark = svgsWithCaptions(section("Logo")).find((x) => x.svg.includes('viewBox="0 0 64 64"'));
if (!mark) throw new Error("logomark not found");
const markSvg = mark.svg.replace(/ width="\d+" height="\d+"/, "");
write("public/brand/logomark.svg", withXmlHeader(markSvg));
write("src/app/icon.svg", withXmlHeader(markSvg));

console.log("Illustrations & mascot");
for (const title of ["Illustration", "Linh vật", "Minh họa cho các khối"]) {
  for (const { svg, caption } of svgsWithCaptions(section(title))) {
    const name = fileName(caption);
    if (!name) continue;
    const dir = name.startsWith("cu-toc-") ? "mascot" : "illustrations";
    write(`public/brand/${dir}/${name}.svg`, withXmlHeader(svg));
  }
}
const thumb = svgsWithCaptions(section("Illustration")).find((x) => x.svg.includes('viewBox="0 0 320 180"'));
if (thumb) write("public/brand/illustrations/thumb-placeholder.svg", withXmlHeader(thumb.svg));

// Icons are not generated: the site uses Phosphor duotone (src/shared/ui/icons.tsx, ADR-010).

console.log("Themes");
const skins = [...section("Skin theo dịp").matchAll(/<div class="card" style="background:(#\w+);border-color:(#\w+)">([\s\S]*?)<small>themes\/([\w-]+)\.css<\/small>/g)].map(
  (m) => {
    const swatches = [...m[3].matchAll(/background:(#\w+)/g)].map((s) => s[1]);
    const [ember, emberGlow, panel, panelRaised, cream] = swatches;
    return { name: m[4], night: m[1], line: m[2], ember, emberGlow, panel, panelRaised, cream };
  },
);
if (skins.length < 4) throw new Error(`expected 4 skins, found ${skins.length}`);
write(
  "src/shared/design/themes.generated.css",
  `/* GENERATED by scripts/extract-brand.mjs from docs/design/brand.html — do not edit.
   Seasonal skins: set data-theme on <html>. Only colour tokens change; logo, icons
   and layout stay the same. "default" is tokens.css itself. */
${skins
  .filter((s) => s.name !== "default")
  .map(
    (s) => `
:root[data-theme="${s.name}"] {
  --td-night: ${s.night};
  --td-line: ${s.line};
  --td-ember: ${s.ember};
  --td-ember-glow: ${s.emberGlow};
  --td-panel: ${s.panel};
  --td-panel-raised: ${s.panelRaised};
  --td-cream: ${s.cream};
}`,
  )
  .join("\n")}
`,
);
console.log("done");
